    private void btnIngresarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnIngresarActionPerformed
        String usuarioIngresado = txtUsuario.getText().trim();
        String contrasenaIngresada = new String(txtContrasena.getPassword()).trim();

        if (usuarioIngresado.isEmpty() || contrasenaIngresada.isEmpty()) {
            javax.swing.JOptionPane.showMessageDialog(
                    this,
                    "Por favor, ingrese usuario y contraseña.",
                    "Campos incompletos",
                    javax.swing.JOptionPane.WARNING_MESSAGE
            );
            return;
        }

        try {
            dao.UsuarioDAO usuarioDAO = new dao.UsuarioDAO();

            modelo.Usuario usuario = usuarioDAO.autenticarUsuario(
                    usuarioIngresado,
                    contrasenaIngresada
            );

            if (usuario == null) {
                javax.swing.JOptionPane.showMessageDialog(
                        this,
                        "Usuario o contraseña incorrectos, o cuenta inactiva.",
                        "Error de Acceso",
                        javax.swing.JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            modelo.Sesion.iniciar(usuario);

            if (usuario instanceof modelo.Administrador) {
                new FrmPanelPrincipal().setVisible(true);

            } else if (usuario instanceof modelo.Empleado) {
                new FrmPanelPrincipalEmpleado().setVisible(true);

            } else {
                javax.swing.JOptionPane.showMessageDialog(
                        this,
                        "El tipo de usuario registrado no es válido.",
                        "Error de Acceso",
                        javax.swing.JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            this.dispose();

        } catch (Exception e) {
            javax.swing.JOptionPane.showMessageDialog(
                    this,
                    "Error al conectar con la base de datos: " + e.getMessage(),
                    "Error DB",
                    javax.swing.JOptionPane.ERROR_MESSAGE
            );
        }
    }//GEN-LAST:event_btnIngresarActionPerformed

